$ErrorActionPreference = 'Stop'
$workspaceRoot = 'C:\public\project-hyle\hyle'
$stageRoot = Join-Path $workspaceRoot '.scratch\architecture-refactor-2026-10-18\fixed-role-binding-2026-10-21\root'
$planPath = Join-Path $stageRoot 'cleanup-plan.json'
$receiptPath = Join-Path $workspaceRoot 'docs\evidence\correctness\blockwise-w4a8-reference-2026-10-21.cleanup.json'
if (Test-Path -LiteralPath $receiptPath) { throw 'This exact cleanup has completed. Do not rerun.' }
$plan = Get-Content -LiteralPath $planPath -Raw -Encoding UTF8 | ConvertFrom-Json
$allowedRoot = (Resolve-Path -LiteralPath $plan.root).ProviderPath.TrimEnd('\') + '\'
$expectedRoot = (Join-Path $workspaceRoot '.scratch\architecture-refactor-2026-10-18\fixed-role-binding-2026-10-21\blockwise-w4a8').TrimEnd('\') + '\'
if ($allowedRoot -ine $expectedRoot) { throw 'Unexpected exact cleanup root.' }
function Assert-Identity($entry) {
 $item = Get-Item -LiteralPath $entry.path
 if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Expected an ordinary exact file.' }
 if ($item.Length -ne $entry.bytes) { throw "Changed size: $($entry.path)" }
 if ((Get-FileHash -LiteralPath $entry.path -Algorithm SHA256).Hash -ine $entry.sha256) { throw "Changed hash: $($entry.path)" }
}
foreach ($entry in $plan.archives) { Assert-Identity $entry }
foreach ($entry in $plan.protected) { Assert-Identity $entry }
foreach ($entry in $plan.targets) {
 $resolved = (Resolve-Path -LiteralPath $entry.path).ProviderPath
 if (-not $resolved.StartsWith($allowedRoot,[StringComparison]::OrdinalIgnoreCase)) { throw 'Target escapes the exact batch.' }
 if ([IO.Path]::GetExtension($resolved) -notin @('.exe','.map','.lib','.exp')) { throw 'Unexpected deletion extension.' }
 Assert-Identity $entry
}
$remoteText = Get-Content -LiteralPath (Join-Path $stageRoot 'cleanup_mac.py') -Raw -Encoding UTF8 | & ssh -o BatchMode=yes -o ConnectTimeout=15 kiro@172.22.10.198 python3 -
if ($LASTEXITCODE -ne 0) { throw 'Mac exact-file cleanup failed; Windows files remain.' }
$remoteReceipt = $remoteText | ConvertFrom-Json
if ($remoteReceipt.status -ne 'complete') { throw 'Unexpected Mac cleanup receipt.' }
$remoteText | Set-Content -LiteralPath (Join-Path $stageRoot 'cleanup-mac-result.json') -Encoding utf8
foreach ($entry in $plan.targets) { Remove-Item -LiteralPath $entry.path -Force }
foreach ($entry in $plan.protected) { Assert-Identity $entry }
foreach ($entry in $plan.targets) { if (Test-Path -LiteralPath $entry.path) { throw 'Deletion incomplete.' } }
$receipt = [ordered]@{
 status = 'complete'
 Windows_removed_files = @($plan.targets).Count
 Windows_removed_bytes = $plan.removed_bytes
 Windows_targets = $plan.targets
 Windows_protected = $plan.protected
 Mac = $remoteReceipt
 archives = $plan.archives
 cleanup_script_sha256 = (Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant()
 cleanup_script = Get-Content -LiteralPath $PSCommandPath -Raw
 remote_cleanup_script = Get-Content -LiteralPath (Join-Path $stageRoot 'cleanup_mac.py') -Raw
 scope = $plan.scope
}
$receipt | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $receiptPath -Encoding utf8
Write-Output "Removed Windows $($plan.removed_bytes) bytes and Mac $($remoteReceipt.removed_bytes) bytes; all protected objects, Qwen consumer and shared caches remain."

